import{_ as t,H as a,f as i,i as E}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"阶段自测题（一）","description":"","frontmatter":{},"headers":[{"level":3,"title":"基础知识","slug":"基础知识","link":"#基础知识","children":[]},{"level":3,"title":"提示词应用","slug":"提示词应用","link":"#提示词应用","children":[]},{"level":3,"title":"AI Agent 应用","slug":"ai-agent-应用","link":"#ai-agent-应用","children":[]}],"relativePath":"AI大模型项目落地实战/阶段自测题（一）.md","filePath":"AI大模型项目落地实战/阶段自测题（一）.md","lastUpdated":1795453306000}'),n={name:"AI大模型项目落地实战/阶段自测题（一）.md"};function l(A,e,p,s,r,o){return a(),i("div",null,[...e[0]||(e[0]=[E('<h1 id="阶段自测题-一" tabindex="-1">阶段自测题（一） <a class="header-anchor" href="#阶段自测题-一" aria-label="Permalink to &quot;阶段自测题（一）&quot;">​</a></h1><p>你好，我是晓蕾。</p><p>到目前为止，咱们课程的四大案例已经更新完了，分别涉及提示词、AI Agent、模型微调以及模型评估 4 个方面。</p><p>从下周开始，我们将要进入的案例追踪阶段，课程将开始每周两更（每周二 / 四）更新的节奏，以更长的间隔呈现更多的案例实况，为你转型 AI 应用人才打下更坚实的基础。</p><p>在案例追踪之前，我们还准备了几道题目，测试下你是否掌握了前几个案例的基础知识。如果有不太熟悉的地方，你可以回到对应的课程里再复习复习。</p><p>好，请听题。</p><h3 id="基础知识" tabindex="-1">基础知识 <a class="header-anchor" href="#基础知识" aria-label="Permalink to &quot;基础知识&quot;">​</a></h3><ol><li><p>请简单描述 Transformer 的基本流程。</p></li><li><p>大模型应用的开发可以分为哪三个层次？每个层次都是什么意思？</p></li></ol><h3 id="提示词应用" tabindex="-1">提示词应用 <a class="header-anchor" href="#提示词应用" aria-label="Permalink to &quot;提示词应用&quot;">​</a></h3><p>我们在 C 语言判题系统里说过，逻辑控制才是 C 语言自动判题系统的核心。现在有一个需求，请你统计极客时间 2024 年截至目前发布的“体系课”。要求按照：后端 / 架构、前端 / 移动、计算机基础、AI/ 大数据、运维 / 测试、产品 / 运营、管理 / 成长的标签分类。得到结果后，再去掉两个相对不感兴趣的分类。</p><p>基于这个需求，你会怎么设计提示词？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/%25E9%2598%25B6%25E6%25AE%25B5%25E8%2587%25AA%25E6%25B5%258B%25E9%25A2%2598%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/%25E9%2598%25B6%25E6%25AE%25B5%25E8%2587%25AA%25E6%25B5%258B%25E9%25A2%2598%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589/1.png" alt=""></a></p><p>提示：控制点 1，统计全部；控制点 2，去掉两个；一步步来。</p><h3 id="ai-agent-应用" tabindex="-1">AI Agent 应用 <a class="header-anchor" href="#ai-agent-应用" aria-label="Permalink to &quot;AI Agent 应用&quot;">​</a></h3><p>Agent 智能体的四要素分别为感知、决策、规划、执行。</p><ol><li><p>请你为四个要素的可靠度排序。</p></li><li><p>设计一个“趣味工牌”系统。（灵感来源：Coze 作品“00 后抽象工牌生成器”，作者西二旗生活指北）</p></li></ol><p>工牌分为 3 部分：花名、个性签名、个性头像。它们的关系是这样的：输入个人姓氏，即可根据姓氏的谐音生成花名，搭配任意个性签名以及任意头像，做出趣味工牌。比如：</p><ul><li><p>输入“耿”，花名为“跟（geng）上进度条”，个性签名为“工作太苦，想逃。”</p></li><li><p>输入“苏”，花名为“苏服的摸鱼侠”，个性签名为“再忙也得偷闲。”</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/%25E9%2598%25B6%25E6%25AE%25B5%25E8%2587%25AA%25E6%25B5%258B%25E9%25A2%2598%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/%25E9%2598%25B6%25E6%25AE%25B5%25E8%2587%25AA%25E6%25B5%258B%25E9%25A2%2598%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589/2.png" alt=""></a></p><ul><li>（趣味优先，非小编 / 平台观点！请努力成长～）</li></ul><p>请拆解，作为一个趣味工牌 AI Agent，哪部分为感知，哪部分为决策，哪部分为规划，哪部分为执行？</p><p>以上题目为提示词 +AI Agent 的测试题目，快来留言区互动吧！看看你能否拆解出 AI 应用项目的背后逻辑！</p><p>我们下次测试题再见～</p>',23)])])}const g=t(n,[["render",l]]);export{h as __pageData,g as default};
